import { test, expect } from '@playwright/test';

test.describe('Form Submission with Past-Date Field', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form-page'); // Replace with the actual form page URL
  });

  test('should show an error when a future date is submitted', async ({ page }) => {
    await page.fill(getByLabel('Date Field'), '12/31/2025'); // Replace with the actual label for the date field
    await page.click(getByRole('button', { name: 'Submit' })); // Replace with the actual button name
    const errorMessage = await page.getByText('Please enter a valid past date.'); // Replace with the actual error message
    await expect(errorMessage).toBeVisible();
  });

  test('should not show an error when a past date is submitted', async ({ page }) => {
    await page.fill(getByLabel('Date Field'), '01/01/2020'); // Replace with the actual label for the date field
    await page.click(getByRole('button', { name: 'Submit' })); // Replace with the actual button name
    const errorMessage = page.getByText('Please enter a valid past date.'); // Replace with the actual error message
    await expect(errorMessage).not.toBeVisible();
  });
});
